using Store;

namespace Store.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup() => _cart = new ShoppingCart();

    // ── AddItem ─────────────────────────────────────────────────────

    [TestMethod]
    public void AddItem_SingleItem_AppearsInCart()
    {
        _cart.AddItem("SKU-001", 2, 9.99m);

        Assert.Contains("SKU-001", _cart.Items.Keys);
        Assert.AreEqual(2, _cart.Items["SKU-001"].Quantity);
        Assert.AreEqual(9.99m, _cart.Items["SKU-001"].Price);
    }

    [TestMethod]
    public void AddItem_DuplicateSku_AccumulatesQuantity()
    {
        _cart.AddItem("SKU-001", 1, 5.00m);
        _cart.AddItem("SKU-001", 3, 5.00m);

        Assert.AreEqual(4, _cart.Items["SKU-001"].Quantity);
    }

    [TestMethod]
    public void AddItem_MultipleSkus_AllPresent()
    {
        _cart.AddItem("A", 1, 10m);
        _cart.AddItem("B", 2, 20m);

        Assert.HasCount(2, _cart.Items);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void AddItem_NullOrEmptySku_Throws(string? sku)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.AddItem(sku!, 1, 10m));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    public void AddItem_InvalidQuantity_Throws(int qty)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() => _cart.AddItem("X", qty, 10m));
    }

    [TestMethod]
    public void AddItem_NegativePrice_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() => _cart.AddItem("X", 1, -1m));
    }

    // ── RemoveItem ──────────────────────────────────────────────────

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovesFromCart()
    {
        _cart.AddItem("SKU-001", 1, 10m);

        _cart.RemoveItem("SKU-001");

        Assert.IsEmpty(_cart.Items);
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_ThrowsKeyNotFound()
    {
        Assert.ThrowsExactly<KeyNotFoundException>(() => _cart.RemoveItem("MISSING"));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    public void RemoveItem_NullOrEmptySku_Throws(string? sku)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.RemoveItem(sku!));
    }

    // ── CalculateTotal ──────────────────────────────────────────────

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_SingleItem_ReturnsCorrectTotal()
    {
        _cart.AddItem("A", 3, 10m);

        Assert.AreEqual(30m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_MultipleItems_SumsAll()
    {
        _cart.AddItem("A", 2, 5m);   // 10
        _cart.AddItem("B", 1, 20m);  // 20

        Assert.AreEqual(30m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_AfterRemoval_ExcludesRemovedItem()
    {
        _cart.AddItem("A", 1, 100m);
        _cart.AddItem("B", 1, 50m);
        _cart.RemoveItem("A");

        Assert.AreEqual(50m, _cart.CalculateTotal());
    }

    // ── ApplyCoupon ─────────────────────────────────────────────────

    [TestMethod]
    [DataRow("SAVE10", 90)]
    [DataRow("SAVE20", 80)]
    [DataRow("HALF", 50)]
    public void ApplyCoupon_ValidCode_DiscountsTotal(string code, int expectedTotal)
    {
        _cart.AddItem("A", 1, 100m);

        _cart.ApplyCoupon(code);

        Assert.AreEqual((decimal)expectedTotal, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_CaseInsensitive_Works()
    {
        _cart.AddItem("A", 1, 100m);

        _cart.ApplyCoupon("save10");

        Assert.AreEqual(90m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_InvalidCode_Throws()
    {
        var ex = Assert.ThrowsExactly<ArgumentException>(() => _cart.ApplyCoupon("BOGUS"));
        Assert.Contains("BOGUS", ex.Message);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    public void ApplyCoupon_NullOrEmpty_Throws(string? code)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.ApplyCoupon(code!));
    }

    [TestMethod]
    public void ApplyCoupon_ReplacesExistingCoupon()
    {
        _cart.AddItem("A", 1, 100m);
        _cart.ApplyCoupon("SAVE10");
        _cart.ApplyCoupon("SAVE20");

        Assert.AreEqual(80m, _cart.CalculateTotal());
    }

    // ── Integration / combined scenarios ────────────────────────────

    [TestMethod]
    public void FullWorkflow_AddRemoveCouponTotal_Correct()
    {
        _cart.AddItem("SHIRT", 2, 25m);   // 50
        _cart.AddItem("HAT", 1, 15m);     // 15
        _cart.RemoveItem("HAT");           // -15
        _cart.ApplyCoupon("SAVE10");       // 10% off

        Assert.AreEqual(45m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_ZeroPriceItem_ReturnsZero()
    {
        _cart.AddItem("FREEBIE", 5, 0m);

        Assert.AreEqual(0m, _cart.CalculateTotal());
    }
}

